{
  "name": "@omnichroma/opencode-stats-for-nerds",
  "version": "2.0.0",
  "description": "OpenCode v2 TUI plugin — token usage, speed, and cost stats in the sidebar",
  "author": "imluckii",
  "license": "MIT",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/omni-/opencode-stats-for-nerds.git"
  },
  "homepage": "https://github.com/omni-/opencode-stats-for-nerds#readme",
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "stats",
    "tokens",
    "tui",
    "sidebar"
  ],
  "exports": {
    "./tui": { "import": "./tui.tsx" }
  },
  "files": [
    "tui.tsx",
    "stats.ts",
    "session.ts",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "node --conditions=browser --test test/*.test.ts",
    "test:tui": "bun --preload @opentui/solid/preload test/tui-smoke.tsx"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.18"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.12",
    "@opentui/solid": ">=0.5.12",
    "solid-js": ">=1.9.10"
  },
  "devDependencies": {
    "@opencode/client": "^2.0.18",
    "@opencode/theme": "2.0.18",
    "@types/node": "^24.0.0",
    "typescript": "^5.9.3"
  }
}
